PAYLOAD = {"sha256":"0910b85270777b546f5b41a73fac41ba473f10046b1e74713f49c016098c7021","data":""}
UPGRADE = {"sha256":"a8c5f5aac4df979662358fd601b257a181ed85233245f172625d2f4b1ec15c36","data":""}


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None


def installed_source():
    dist = importlib.metadata.distribution("vllm-ascend")
    direct = json.loads(dist.read_text("direct_url.json") or "{}")
    if direct.get("dir_info", {}).get("editable") and direct.get("url", "").startswith("file:"):
        return pathlib.Path(unquote(urlparse(direct["url"]).path))
    raise SystemExit("Cannot locate editable VA. Pass --source /absolute/path/to/VA.")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=pathlib.Path)
    parser.add_argument("--check", action="store_true", help="Read-only preflight; do not apply.")
    args = parser.parse_args()
    root = (args.source or installed_source()).resolve()
    if not (root / "vllm_ascend/ascend_config.py").is_file():
        raise SystemExit("Not a VA source directory: " + str(root))
    for name in AFTER:
        path = root / name
        if not path.resolve().is_relative_to(root) or path.is_symlink():
            raise SystemExit("Refusing symlink/outside source target: " + name)
    actual = {name: digest(root / name) for name in AFTER}
    if actual == AFTER:
        print("QFM_VA030_UNIT_SCALE_ALREADY_APPLIED source=" + str(root))
        return
    head = subprocess.check_output(["git", "-C", str(root), "rev-parse", "HEAD"], text=True).strip()
    if head != BASE:
        raise SystemExit("Base mismatch: expected " + BASE + ", got " + head + "; no files changed.")
    if actual == BEFORE:
        payload, mode = PAYLOAD, "clean_install"
    elif actual == LEGACY:
        payload, mode = UPGRADE, "upgrade_2873327"
    else:
        mismatches = [name for name in AFTER if actual[name] not in (BEFORE[name], LEGACY[name], AFTER[name])]
        raise SystemExit("Unknown or mixed patch state; no files changed. Do not force/reset.\n" + "\n".join(mismatches))
    patch = gzip.decompress(base64.b64decode(payload["data"]))
    if hashlib.sha256(patch).hexdigest() != payload["sha256"]:
        raise SystemExit("Embedded patch checksum failed; no files changed.")
    subprocess.run(["git", "-C", str(root), "apply", "--check", "-"], input=patch, check=True)
    if args.check:
        print("QFM_VA030_PREFLIGHT_OK mode=" + mode + " source=" + str(root))
        return
    backup = pathlib.Path(tempfile.mkdtemp(prefix="va030-qfm-unit-backup-"))
    for name, old_hash in actual.items():
        if old_hash is not None:
            dest = backup / name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(root / name, dest)
    (backup / "manifest.json").write_text(json.dumps({"source": str(root), "base": BASE, "before": actual, "after": AFTER}, indent=2))
    subprocess.run(["git", "-C", str(root), "apply", "-"], input=patch, check=True)
    if any(digest(root / name) != expected for name, expected in AFTER.items()):
        raise SystemExit("Post-apply hash mismatch. Stop and inspect; backup=" + str(backup))
    for name in AFTER:
        if name.endswith(".py"):
            compile((root / name).read_text(), name, "exec")
    print("QFM_VA030_UNIT_SCALE_APPLIED mode=" + mode + " source=" + str(root))
    print("BACKUP=" + str(backup))
    print("KV descale is internal 1.0, matching the pinned official K3 recipe.")
    print("REMOVE qfm_kv_scale from additional-config; it is no longer a valid field.")
    print("RESTART ALL WORKERS: never reuse cache pages written with the previous scale.")
    print("No native packages installed; no NPU/model tests run. Full-model accuracy remains unvalidated.")
    print("NEXT native writer check:")
    print("python " + str(root / "tests/e2e/nightly/single_node/ops/singlecard_ops/check_kimi_k3_qfm_writer.py") + " --card 0")


if __name__ == "__main__":
    main()
